const cuerpo = JSON.parse(responseBody);

if (!cuerpo.access_token) {
  console.log('No hubo token. Status ' + response.code + ': ' + responseBody);
  return;
}

// El environment de la coleccion, no el del folder: asi lo lee tambien la
// otra coleccion cuando muevas las requests alla.
const env = insomnia.environments.get('workspace');
env.token = cuerpo.access_token;
env.expires_at = new Date(Date.now() + cuerpo.expires_in * 1000).toISOString();
insomnia.environments.set('workspace', env);

console.log('Token guardado en {{ _.token }}. Expira en ' + cuerpo.expires_in + ' s (' + env.expires_at + ').');
